		"content": "{\n\t\"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n\t\"$id\": \"https://github.com/HeiCg/svelte-grab/skills/svelte-grab-audit/finding-schema.json\",\n\t\"title\": \"svelte-grab audit findings\",\n\t\"description\": \"Findings of a svelte-grab security/performance audit. The finding shape is the one ui_security_scan returns (docs/agent-runtime-spec.md 9b) and svelte-grab audit emits (9c). Static findings from `svelte-grab audit` (src/cli/audit/finding-schema.json) also carry rule, file, line and column and validate here too.\",\n\t\"type\": \"object\",\n\t\"required\": [\"findings\"],\n\t\"properties\": {\n\t\t\"generatedAt\": { \"type\": \"string\", \"description\": \"ISO 8601 timestamp.\" },\n\t\t\"tool\": { \"type\": \"string\", \"description\": \"What produced the findings, e.g. \\\"svelte-grab audit\\\", \\\"ui_security_scan\\\", \\\"svelte-grab-audit skill\\\".\" },\n\t\t\"findings\": {\n\t\t\t\"type\": \"array\",\n\t\t\t\"items\": { \"$ref\": \"#/$defs/finding\" }\n\t\t}\n\t},\n\t\"$defs\": {\n\t\t\"finding\": {\n\t\t\t\"type\": \"object\",\n\t\t\t\"required\": [\"id\", \"severity\", \"verdict\", \"title\", \"evidence\", \"fix\"],\n\t\t\t\"properties\": {\n\t\t\t\t\"id\": { \"type\": \"string\", \"minLength\": 1, \"description\": \"Stable rule or check id.\" },\n\t\t\t\t\"severity\": { \"enum\": [\"high\", \"medium\", \"low\", \"info\"] },\n\t\t\t\t\"verdict\": {\n\t\t\t\t\t\"enum\": [\"confirmed\", \"needs_validation\"],\n\t\t\t\t\t\"description\": \"confirmed needs reproduction evidence; needs_validation must name the missing fact. Disproved candidates are not findings.\"\n\t\t\t\t},\n\t\t\t\t\"title\": { \"type\": \"string\", \"minLength\": 1 },\n\t\t\t\t\"evidence\": {\n\t\t\t\t\t\"type\": \"string\",\n\t\t\t\t\t\"description\": \"Redacted evidence. Secrets appear only as kind:abcd…(len N, sha xxxxxx), never in full.\"\n\t\t\t\t},\n\t\t\t\t\"source\": { \"type\": \"string\", \"description\": \"file:line when known.\" },\n\t\t\t\t\"rule\": { \"type\": \"string\", \"description\": \"Static rule id from svelte-grab audit, e.g. secrets/client-exposure.\" },\n\t\t\t\t\"file\": { \"type\": \"string\", \"description\": \"Project-relative file (static findings).\" },\n\t\t\t\t\"line\": { \"type\": \"integer\", \"minimum\": 1 },\n\t\t\t\t\"column\": { \"type\": \"integer\", \"minimum\": 1 },\n\t\t\t\t\"fix\": { \"type\": \"string\", \"minLength\": 1 },\n\t\t\t\t\"check\": { \"type\": \"string\", \"description\": \"ui_security_scan check (transit, storage, ...) or CHECKLIST.md id (S1, P4, ...).\" },\n\t\t\t\t\"screen\": { \"type\": \"string\", \"description\": \"Route of the screen the finding was observed on.\" },\n\t\t\t\t\"missingFact\": { \"type\": \"string\", \"description\": \"For needs_validation: the exact fact that would confirm or reject it.\" }\n\t\t\t},\n\t\t\t\"additionalProperties\": true\n\t\t}\n\t}\n}\n"
